import n from'fs/promises';import c from'os';import r from'path';import l from'readline';import {fileURLToPath}from'url';function y(e){e.command("setup [integration]").description("Show setup status or explicitly configure an integration").option("--yes","Confirm the requested configuration change").action(async(o,t)=>{if(!o){console.log("ORCH is installed. No user configuration was changed."),console.log("Optional: orch setup claude-integration");return}if(o!=="claude-integration")throw new Error(`Unsupported integration: ${o}`);if(!(t.yes===true||await m("Install the ORCH skill under ~/.claude/skills/orch?"))){console.log("No changes made.");return}let a=await u(),i=r.join(c.homedir(),".claude","skills","orch","SKILL.md");await n.mkdir(r.dirname(i),{recursive:true,mode:448}),await n.copyFile(a,i),await n.chmod(i,384).catch(()=>{}),console.log(`Installed Claude integration: ${i}`);});}async function m(e){if(!process.stdin.isTTY||!process.stdout.isTTY)return  false;let o=l.createInterface({input:process.stdin,output:process.stdout});try{let t=await new Promise(s=>o.question(`${e} [y/N] `,s));return /^y(?:es)?$/i.test(t.trim())}finally{o.close();}}async function u(){let e=r.dirname(fileURLToPath(import.meta.url)),o=[r.resolve(e,"..","skills","orch","SKILL.md"),r.resolve(e,"..","..","..","skills","orch","SKILL.md")];for(let t of o)try{return await n.access(t),t}catch{}throw new Error("Packaged Claude integration is missing")}export{y as registerSetupCommand};